"""Generate crawlable archive pages from the same data used by the test app."""
from pathlib import Path
from collections import Counter
from html import escape as e
import json
from campus_tools import navigation, footer, context, switcher

ROOT = Path(__file__).resolve().parent.parent
BASE = 'https://cikmissorular.pdrkampus.com/'
YEARS = list(range(2014, 2027))
DATA = {y: json.loads((ROOT / f'data/{y}.json').read_text()) for y in YEARS}
CLASS = json.loads((ROOT / 'data/topic-classification-draft.json').read_text())
CATEGORIES = CLASS['categories']
IDS = {q['id'] for d in DATA.values() for q in d['questions']}
ROWS = [r for r in CLASS['questions'] if r['id'] in IDS and r['category'] in CATEGORIES]
TOPICS = [
 ('temel-psikolojik-kavramlar', 'Psikolojinin temel kavramlarını aynı testte tekrar et. Kavramları yalnızca tanımlarıyla değil, soru kökünde anlatılan durumla birlikte değerlendirmek bu alandaki çalışmanın temelidir.', 'Soru kökündeki belirleyici ifadeleri işaretle. Birbirine yakın kavramları kısa bir karşılaştırma tablosunda topla; yanlış seçtiğin şıkla doğru yanıtın neden farklı olduğunu kendi cümlenle yaz.'),
 ('psikolojik-danisma-kuram-ilke-teknikleri', 'Psikolojik danışma kuramları, ilkeleri ve teknikleri üzerine sorularla çalış. Kuramların insan doğasına bakışı, danışmanın rolü ve kullanılan teknikler arasındaki farkları birlikte düşün.', 'Kuramları amaç, temel kavram ve teknik başlıklarıyla karşılaştır. Bir vakayı okurken hangi kuramın yaklaşımına uyduğunu belirle; yalnızca tek bir anahtar sözcüğe dayanarak yanıt verme.'),
 ('davranis-ve-uyum-problemleri', 'Davranış ve uyum problemlerini konu alan PDR ÖABT sorularını bir arada çöz. Örnek olaylarda gözlenen davranışı, içinde bulunduğu bağlamı ve danışmanlık açısından önemini birlikte değerlendir.', 'Vaka sorularında davranışın süresini, sıklığını ve bağlamını ayır. Benzer görünen seçenekleri karşılaştırırken soru kökünün gerçekten verdiği bilgilerden hareket et.'),
 ('bireyi-tanima-teknikleri', 'Bireyi tanıma teknikleriyle ilgili çıkmış sorulara odaklan. Bir tekniğin amacı, hangi bilgiyi sağladığı ve hangi durumda kullanılabileceği arasındaki ilişkiyi pekiştir.', 'Teknikleri kullanım amacı ve elde edilen bilgi türüne göre gruplandır. Soruda istenenin veri toplamak mı, gözlemlemek mi yoksa bir durumu değerlendirmek mi olduğunu önce belirle.'),
 ('bireyle-ve-grupla-psikolojik-danisma', 'Bireyle ve grupla psikolojik danışma sorularını tek bir çalışma alanında incele. Danışma süreci, danışmanın tutumu ve grup içindeki ilişkileri örnek olaylar üzerinden değerlendir.', 'Sorunun danışma sürecinin hangi aşamasını anlattığını belirle. Bireysel görüşme ile grup sürecini karşılaştır; danışmanın müdahalesini verilen bağlama göre yorumla.'),
 ('mesleki-rehberlik-ve-kariyer-danismanligi', 'Mesleki rehberlik ve kariyer danışmanlığına ilişkin çıkmış sorularla çalış. Meslek seçimi, kariyer gelişimi ve bireyin özellikleri arasındaki ilişkileri soru örnekleriyle tekrar et.', 'Kariyer yaklaşımlarını temel kavramlarıyla karşılaştır. Vaka sorularında ilgi, yetenek, değer ve yaşam koşullarını birbirinden ayır; sorunun hangi bilgiyi öne çıkardığına dikkat et.'),
 ('arastirma-ve-program-gelistirme', 'Psikolojik danışma ve rehberlikte araştırma ve program geliştirme sorularını birlikte çöz. Araştırmanın amacı, kullanılan yöntem ve programın değerlendirilmesi arasındaki bağlantıları incele.', 'Araştırma sorularında değişkenleri ve yöntemle amaç arasındaki uyumu belirle. Program sorularını ihtiyaç, hedef, uygulama ve değerlendirme adımlarına ayırarak çalış.'),
 ('meslek-etigi-ve-yasal-konular', 'Meslek etiği ve yasal konulara ilişkin çıkmış soruları incele. Mesleki sorumlulukları, danışma ilişkisini ve örnek olaylardaki etik kararları sınav bağlamında ele al.', 'Vakadaki sorumlulukları ve tarafları ayrı ayrı belirle. Eski bir sınav yanıtını güncel mesleki uygulamaya doğrudan taşımadan, uygulamada geçerli mevzuatı ve meslek ilkelerini ayrıca kontrol et.'),
 ('ozel-egitim', 'Özel eğitim başlığındaki PDR ÖABT sorularını bir arada çöz. Bireysel ihtiyaçlar, eğitim desteği ve rehberlik hizmetlerinin rolünü soru örnekleri üzerinden tekrar et.', 'Soru kökündeki eğitim ihtiyacını ve istenen destek türünü ayır. Benzer seçenekleri karşılaştırırken verilen öğrenci özellikleri ile hizmetin amacı arasındaki ilişkiye odaklan.')
]
URLS = [BASE]

def app(query=''):
    return '../../' + ('?' + query if query else '')

def links(items):
    return '<div class="resource-grid">' + ''.join(f'<a class="resource-card" href="{e(url)}"><strong>{e(title)}</strong><span>{e(detail)} →</span></a>' for url,title,detail in items) + '</div>'

def page(path, title, description, heading, intro, body, cta, cta_text, breadcrumbs, items=None):
    url = BASE + path
    URLS.append(url)
    graph = [
      {'@type':'CollectionPage' if items else 'WebPage','@id':url+'#page','url':url,'name':title,'description':description,'inLanguage':'tr-TR','isPartOf':{'@id':BASE+'#website'},'publisher':{'@id':'https://pdrkampus.com/#organization'}},
      {'@type':'WebSite','@id':BASE+'#website','url':BASE,'name':'PDR Kampüs · PDR ÖABT Çıkmış Sorular','inLanguage':'tr-TR'},
      {'@type':'Organization','@id':'https://pdrkampus.com/#organization','name':'PDR Kampüs','url':'https://pdrkampus.com/','logo':BASE+'assets/campus-logo.png'},
      {'@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':i+1,'name':name,'item':u} for i,(name,u) in enumerate(breadcrumbs)]}
    ]
    if items: graph.append({'@type':'ItemList','itemListElement':[{'@type':'ListItem','position':i+1,'name':name,'url':u} for i,(name,u) in enumerate(items)]})
    schema=json.dumps({'@context':'https://schema.org','@graph':graph},ensure_ascii=False).replace('<','\\u003c')
    crumb=''.join(f'<a href="{e(u)}">{e(n)}</a>' for n,u in breadcrumbs[:-1])+f'<span aria-current="page">{e(breadcrumbs[-1][0])}</span>'
    related = context('Hazırlığına devam et', 'AGS / PDR puan ve sıralama tahminleriyle çalışma sürecini destekle.', [('https://analiz.pdrkampus.com/', 'Sınav analizini incele')])
    if path == 'yillar/2026/':
        related = context('2026 sınavını birlikte değerlendir', '2026 PDR ÖABT rehberini incele ve çıkmış sorularla çalışmaya devam et.', [('https://analiz.pdrkampus.com/pdr-oabt/2026/', '2026 PDR ÖABT analizini incele')])
    html=f'''<!doctype html>
<html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{e(title)}</title><meta name="description" content="{e(description)}"><meta name="robots" content="index,follow,max-image-preview:large"><link rel="canonical" href="{url}">
<meta property="og:type" content="website"><meta property="og:locale" content="tr_TR"><meta property="og:site_name" content="PDR Kampüs"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(description)}"><meta property="og:url" content="{url}"><meta property="og:image" content="{BASE}assets/campus-logo.png"><meta name="twitter:card" content="summary"><meta name="theme-color" content="#397d6b">
<link rel="icon" href="../../assets/campus-logo.png"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Manrope:wght@400;500;600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="../../seo.css"><link rel="stylesheet" href="/assets/campus-tools.css?v=20261014-simple-v2"><script type="application/ld+json">{schema}</script></head>
<body><a class="skip" href="#content">İçeriğe geç</a><header><a class="brand" href="../../"><img src="../../assets/campus-logo.png" width="44" height="44" alt=""><strong>PDR<span>kampüs</span></strong></a><nav aria-label="Ana menü"><a href="../../yillar/">Yıllar</a><a href="../../konular/">Konular</a>{switcher("questions")}</nav></header>
<main id="content"><nav class="breadcrumbs" aria-label="Sayfa yolu">{crumb}</nav><section class="intro"><span class="kicker">PDR ÖABT · ÇIKMIŞ SORULAR</span><h1>{e(heading)}</h1><p>{e(intro)}</p><a class="primary" href="{e(cta)}">{e(cta_text)} →</a></section><div class="page-body">{body}</div><aside class="study-band"><h2>Okuduklarını sorularla pekiştir.</h2><p>Sorularını seç, cevaplarını işaretle ve sonuç optiğinden tekrar incele.</p><a class="primary" href="{e(cta)}">{e(cta_text)} →</a></aside>{related}</main>
{footer("questions")}<footer><strong>PDR Kampüs · Soru arşivi</strong><p>Psikolojik danışmanlar için kaynak ve çalışma araçları.</p><nav aria-label="Alt bağlantılar"><a href="../../">Soru çözme alanı</a><a href="../../yillar/">Yıllara göre sorular</a><a href="../../konular/">Konu rehberleri</a><a href="https://pdrkampus.com/iletisim.html">İletişim</a></nav><p class="note">ÖSYM ile kurumsal bir bağlantısı bulunmayan PDR Kampüs çalışma alanıdır. Soru hakları ilgili hak sahiplerine aittir.</p></footer></body></html>'''
    if path.count('/') == 1:
        html = html.replace('../../', '../')
    dest=ROOT/path/'index.html'; dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(html)

for y,d in DATA.items():
    counts=Counter(r['category'] for r in ROWS if r['year']==y)
    n=len(d['questions']); total=n+len(d.get('cancelledQuestions',[]))
    cancellation = '<p>2015 sınavında iptal edilen 21 ve 29. sorular testte yer almaz. Arşivdeki 48 soru üzerinden çalışır ve sonuçlarını görürsün.</p>' if y==2015 else ''
    table='<div class="table-scroll"><table><caption>Bu arşivdeki konu dağılımı</caption><thead><tr><th scope="col">Konu</th><th scope="col">Soru</th></tr></thead><tbody>'+''.join(f'<tr><th scope="row"><a href="../../konular/{slug}/">{e(cat)}</a></th><td>{counts[cat]}</td></tr>' for cat,(slug,_,_) in zip(CATEGORIES,TOPICS))+'</tbody></table></div>'
    neighboring=[z for z in (y-1,y+1) if z in YEARS]
    body=f'<section><h2>{y} PDR ÖABT sorularıyla nasıl çalışabilirsin?</h2><p>Bu sayfadan {y} yılına ait {n} soruluk teste ulaşabilirsin. Çalışma modunda süre sınırı olmadan cevaplarını kontrol et; sınav modunda uygulamanın {d["durationMinutes"]} dakikalık sayacıyla ilerle. Konu modunda ise o yılın sorularını konu başlıklarına göre seç.</p>{cancellation}<div class="facts"><div><strong>{n}</strong><span>çözülebilir soru</span></div><div><strong>{d["durationMinutes"]} dk</strong><span>uygulamadaki sınav süresi</span></div></div></section><section><h2>{y} yılı konu başlıkları</h2><p>Tablo, PDR Kampüs arşivinde bu yılın sorularının hangi çalışma başlıklarında bulunduğunu gösterir. Başlığa dokunarak tüm yılların ilgili konu rehberine geçebilirsin.</p>{table}</section><section><h2>Cevap anahtarı ve tekrar</h2><p>Testte cevaplarını işaretledikten sonra “Sonucunu gör” düğmesiyle doğru, yanlış ve boşlarını birlikte incele. Boş bıraktığın soruların doğru seçenekleri de gösterilir. Tekrar etmek istediklerini “Sonra bak” ile bu tarayıcıdaki test kaydına ekleyebilirsin.</p><p>Önce bir tur soruları çöz, sonra yanlış ve boşlarını konu başlıklarıyla karşılaştır. Aynı konunun başka yıllardaki sorularını çözerek tekrarını genişlet.</p></section><section><h2>Diğer yıllarla devam et</h2>'+links([(f'../../yillar/{z}/',f'{z} PDR ÖABT çıkmış sorular',f'{len(DATA[z]["questions"])} soru') for z in neighboring])+ '<p><a href="../../yillar/">2014–2026 arasındaki bütün yılları incele →</a></p></section>'
    page(f'yillar/{y}/',f'{y} PDR ÖABT Çıkmış Sorular ve Cevap Anahtarı | PDR Kampüs',f'{y} PDR ÖABT çıkmış soruları: {n} soru, konu dağılımı ve cevap anahtarı. Çalışma veya sınav modunu seç, sonuçlarını incele.',f'{y} PDR ÖABT çıkmış sorular',f'{y} yılı sorularını tek testte çöz, konu dağılımını incele ve cevap anahtarıyla tekrar yap. Bu arşivde {n} çözülebilir soru bulunuyor.',body,app(f'year={y}'),f'{y} sorularını çöz',[('Çıkmış sorular',BASE),('Yıllar',BASE+'yillar/'),(str(y),BASE+f'yillar/{y}/')])

for i,(cat,(slug,description,tip)) in enumerate(zip(CATEGORIES,TOPICS)):
    counts=Counter(r['year'] for r in ROWS if r['category']==cat); n=sum(counts.values())
    body=f'<section><h2>Bu konuya nasıl çalışmalısın?</h2><p>{e(tip)}</p><p>Çalışma sırasında yanlış yaptığın soruyu hemen geçmek yerine doğru seçeneği diğerlerinden ayıran ifadeyi bul. “Sonra bak” listesini bu tekrar soruları için kullan; sonuç ekranından soru görselini yeniden aç.</p></section><section><h2>Yıllara göre {e(cat.lower())} soruları</h2><p>Bu başlıkta 2014–2026 arşivinden toplam {n} soru var. Aşağıdaki bağlantılar ilgili yılın bu konuya ait testini doğrudan açar.</p>'+links([(app(f'year={y}&topic={i}'),f'{y} · {cat}',f'{counts[y]} soru') for y in YEARS if counts[y]])+'</section><section><h2>Tek yıl mı, tüm yıllar mı?</h2><p>Bir yıldaki konu soruları kısa tekrar yapmak için uygundur. Tüm yıllar testi ise aynı çalışma başlığındaki soruları tek oturumda bir araya getirir. Konu modunda süre sınırı olmadan çalışabilir, işaretlediğin cevabın doğru veya yanlış olduğunu hemen görebilirsin.</p><p><a href="../../konular/">Diğer konu başlıklarını keşfet →</a> · <a href="../../yillar/">Tam yıl sınavlarını incele →</a></p></section>'
    page(f'konular/{slug}/',f'{cat} Çıkmış Sorular | PDR ÖABT',f'PDR ÖABT {cat.lower()} çıkmış soruları: {n} soru. Yıllara göre soru sayıları, konu tekrarı ve online test PDR Kampüs’te.',f'{cat} çıkmış sorular',description,body,app(f'topic={i}'),f'{n} soruluk konu testini çöz',[('Çıkmış sorular',BASE),('Konular',BASE+'konular/'),(cat,BASE+f'konular/{slug}/')])

page('yillar/', 'PDR ÖABT Yıllara Göre Çıkmış Sorular · 2014–2026 | PDR Kampüs', '2014–2026 PDR ÖABT çıkmış sorularını yıl yıl keşfet. 13 yıl, 798 soru, konu dağılımları ve cevap anahtarlarıyla sınava hazırlan.', 'Yıllara göre PDR ÖABT çıkmış sorular', '2014–2026 arasındaki 13 yılın sorularını bir arada keşfet. Her yılın rehberinden soru sayısına, konu dağılımına ve doğrudan test bağlantısına ulaş.', '<section><h2>Hangi yılın sorularını çözmek istersin?</h2>'+links([(f'../yillar/{y}/',f'{y} PDR ÖABT çıkmış sorular',f'{len(DATA[y]["questions"])} soru · cevap anahtarı') for y in reversed(YEARS)])+'</section><section><h2>798 soruluk arşiv</h2><p>2014–2018 arşivleri 50 soruluk sınavlardan oluşur; 2015’te iptal edilen iki soru çıkarıldığı için o yıl 48 soru içerir. 2019–2024 yıllarının her birinde 75, 2025 ve 2026 yıllarında ise 50 soru yer alır. Böylece arşiv toplam 798 çözülebilir soruyu kapsar.</p><p>Yıl testleri çalışma, sınav ve konu modlarıyla açılır. Belirli bir başlığa odaklanmak için <a href="../konular/">konu rehberlerine</a> de geçebilirsin.</p></section>', '../', 'Soru çözme alanını aç', [('Çıkmış sorular',BASE),('Yıllar',BASE+'yillar/')], [(f'{y} PDR ÖABT',BASE+f'yillar/{y}/') for y in YEARS])
page('konular/', 'PDR ÖABT Konulara Göre Çıkmış Sorular ve Testler | PDR Kampüs', 'PDR ÖABT çıkmış sorularını 9 konu başlığı altında keşfet. Konu rehberleri, yıllara göre soru sayıları ve 2014–2026 online konu testleri.', 'Konulara göre PDR ÖABT çıkmış sorular', 'Tekrarını ihtiyacın olan başlıktan başlat. Dokuz konu rehberinde çalışma önerileri, yıllara göre soru sayıları ve ilgili teste doğrudan bağlantılar bulunuyor.', '<section><h2>Konu başlığını seç</h2>'+links([(f'../konular/{slug}/',cat,f'{sum(1 for r in ROWS if r["category"]==cat)} soru') for cat,(slug,_,_) in zip(CATEGORIES,TOPICS)])+'</section><section><h2>Konu testleriyle eksiklerini fark et</h2><p>Önce çalışmak istediğin başlığı seç. Tüm yılların sorularını tek testte çözebilir veya rehberdeki bağlantılardan bir yılın konu sorularını açabilirsin. Cevaplarını işaretledikçe geri bildirim al; tamamladığında sonuç optiğinden yanlış ve boşlarını yeniden incele.</p><p>Tam bir sınav oturumu için <a href="../yillar/">yıllara göre çıkmış sorular</a> sayfasını kullan.</p></section>', '../?topics=all', 'Konu seçimini aç', [('Çıkmış sorular',BASE),('Konular',BASE+'konular/')],[(cat,BASE+f'konular/{slug}/') for cat,(slug,_,_) in zip(CATEGORIES,TOPICS)])
matrix='<div class="table-scroll"><table><caption>PDR ÖABT arşivinde yıllara ve konulara göre soru dağılımı</caption><thead><tr><th scope="col">Konu</th>'+''.join(f'<th scope="col"><a href="../yillar/{y}/">{y}</a></th>' for y in YEARS)+'<th scope="col">Toplam</th></tr></thead><tbody>'
for cat,(slug,_,_) in zip(CATEGORIES,TOPICS):
    counts=Counter(r['year'] for r in ROWS if r['category']==cat)
    matrix+=f'<tr><th scope="row"><a href="../konular/{slug}/">{e(cat)}</a></th>'+''.join(f'<td>{counts[y]}</td>' for y in YEARS)+f'<td>{sum(counts.values())}</td></tr>'
matrix+='<tr><th scope="row">Çözülebilir soru toplamı</th>'+''.join(f'<td>{len(DATA[y]["questions"])}</td>' for y in YEARS)+f'<td>{sum(len(d["questions"]) for d in DATA.values())}</td></tr></tbody></table></div>'
page('analiz/', 'PDR Konu Dağılımı ve Soru Analizi · 2014–2026 | PDR Kampüs', 'PDR konu dağılımı ve soru dağılımını 2014–2026 yılları için karşılaştır. PDR kaç soru var? 13 yılın soru sayıları ve konu testleri burada.', 'PDR konu dağılımı ve çıkmış soru analizi', 'PDR ÖABT arşivindeki 798 sorunun dokuz konu başlığına ve 13 sınav yılına göre dağılımını incele. Tekrar planını gerçek arşiv sayılarına göre oluştur.', '<section><h2>PDR soru dağılımı: hangi konuda kaç soru var?</h2><p>Aşağıdaki tablo bu sitedeki çıkmış soruların konu başlıklarına göre sınıflandırılmasından oluşturulmuştur. Resmî sınav kapsamı veya gelecekteki sınav için soru ağırlığı tahmini değildir. Sütunlardan yılları, satırlardan konu rehberlerini açabilirsin.</p>'+matrix+'</section><section><h2>PDR kaç soru var?</h2><p>Bu arşivde 2014–2018 sınavları 50 soruluk, 2019–2024 sınavları 75 soruluk ve 2025–2026 sınavları 50 soruluk kitapçıklar üzerinden yer alıyor. 2015 sınavındaki iki iptal soru değerlendirme dışında olduğu için 48 çözülebilir soru bulunuyor. Toplam 798 soru çözebilirsin.</p><p>Soru sayısı ve sınav biçimi yıllara göre değişebileceğinden hazırlık yaptığın dönemin güncel sınav bilgileri için <a href="https://www.osym.gov.tr/">ÖSYM duyurularını ve sınav kılavuzunu</a> kontrol et.</p></section><section><h2>PDR analizini çalışma planına nasıl dönüştürebilirsin?</h2><p>Konu toplamları arşivdeki kapsamı gösterir; yüksek soru sayısı tek başına öncelik belirlemez. Önce bir yılın sorularını çöz, yanlış ve boşlarını incele. Sonra eksik olduğun başlığın tüm yıllar testine geç. Böylece çalışma süreni kendi sonuçlarına göre dağıtırsın.</p><p>Bu sayfadaki analiz soru sayılarını karşılaştırır. Puanını hesaplamak için <a href="https://analiz.pdrkampus.com/">AGS/PDR puan hesaplama aracını</a> kullanabilirsin.</p></section><section><h2>PDR çıkmış soru çöz</h2><p><a href="../yillar/">Yıllara göre PDR çıkmış soruları</a> incele veya <a href="../konular/">konu başlığına göre testini seç</a>. Çalışma modunda anında geri bildirim alabilir, sınav modunda süreli bir oturum yapabilirsin.</p></section>', '../', 'PDR çıkmış soru çöz', [('Çıkmış sorular',BASE),('Konu dağılımı ve analiz',BASE+'analiz/')])
(ROOT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+''.join(f'  <url><loc>{e(url)}</loc></url>\n' for url in URLS)+'</urlset>\n')
